css:
.d-confirmation-field-match{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-confirmation-field-match *,.d-confirmation-field-match *::before,.d-confirmation-field-match *::after{box-sizing:border-box}
.d-confirmation-field-match [hidden]{display:none!important}
.d-confirmation-field-match .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-confirmation-field-match .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-confirmation-field-match label{display:block;margin:8px 0}
.d-confirmation-field-match input,.d-confirmation-field-match select,.d-confirmation-field-match textarea,.d-confirmation-field-match button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-confirmation-field-match input:not([type=checkbox]):not([type=radio]),.d-confirmation-field-match select,.d-confirmation-field-match textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-confirmation-field-match button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-confirmation-field-match button:disabled{opacity:.5;cursor:default}
.d-confirmation-field-match :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-confirmation-field-match [aria-invalid=true]{border-color:var(--warn)!important}
.d-confirmation-field-match .d-scroll{max-width:100%;overflow:auto}
.d-confirmation-field-match table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-confirmation-field-match th,.d-confirmation-field-match td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-confirmation-field-match caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-confirmation-field-match progress{width:100%;accent-color:var(--ink)}
.d-confirmation-field-match pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-confirmation-field-match h3,.d-confirmation-field-match p{margin:8px 0}
.d-confirmation-field-match [aria-pressed=true],.d-confirmation-field-match [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-confirmation-field-match .d-grow{flex:1;min-width:100px}
.d-confirmation-field-match summary{cursor:pointer;padding:6px 0}
.d-confirmation-field-match ul,.d-confirmation-field-match ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const sync=()=>{const first=q('[data-first]'),second=q('[data-second]'),valid=first.value.length>0&&first.value===second.value;q('[data-confirm]').disabled=!valid;second.setAttribute('aria-invalid',String(Boolean(second.value)&&!valid));say(valid?'两次输入一致':second.value?'两次输入不一致':'请再次输入确认');};qa('input').forEach(el=>{el.autocomplete='new-password';el.oninput=sync;});q('[data-confirm]').onclick=()=>say('已通过本地一致性检查');sync();})(root, q, qa, say);
}
